/* Card proportions and image framing: registered media-frames exception.
   Category colors express card identity, never execution status. */
.ds-agent-card-face {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
  aspect-ratio: 244 / 352;
  isolation: isolate;
  border: var(--ds-border-strong, 2px) solid var(--ds-category-amber-text-default, #926200);
  border-radius: var(--ds-radius-field, 0.75rem);
  background: var(--ds-neutral-subtle-default, #faf7f6);
  color: var(--ds-ink-default-default, #1d1d1d);
  overflow: visible;
}
.ds-agent-card-face::after {
  content: '';
  position: absolute;
  inset: calc(var(--ds-space-control-gap, 0.5rem) / 2);
  border: 1px solid var(--ds-category-amber-border-default, #ffd192);
  border-radius: var(--ds-radius-compact-control, 0.5rem);
  pointer-events: none;
}
.ds-agent-card-face--silver {
  border-color: var(--ds-category-slate-text-default, #5d646e);
}
.ds-agent-card-face--ink {
  border-color: var(--ds-ink-default-default, #1d1d1d);
}
.ds-agent-card-face--silver::after,
.ds-agent-card-face--ink::after {
  border-color: var(--ds-category-slate-border-default, #ccd1d9);
}
.ds-agent-card-art {
  position: absolute;
  inset: calc(var(--ds-space-control-gap, 0.5rem) * 0.75)
    calc(var(--ds-space-control-gap, 0.5rem) * 0.75);
  z-index: -1;
  border-radius: var(--ds-radius-compact-control, 0.5rem);
  overflow: hidden;
  background: var(--ds-neutral-muted-default, #e7e4e3);
}
.ds-agent-card-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}
.ds-agent-card-face--full .ds-agent-card-art--square img {
  height: 74%;
}
.ds-agent-card-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--ds-space-control-gap, 0.5rem);
  margin: calc(var(--ds-space-control-gap, 0.5rem) * 1.25)
    calc(var(--ds-space-control-gap, 0.5rem) * 1.25) 0;
  padding: calc(var(--ds-space-control-gap, 0.5rem) / 2)
    calc(var(--ds-space-control-gap, 0.5rem) * 0.75);
  border-radius: var(--ds-radius-compact-control, 0.5rem);
  background: var(--ds-neutral-subtle-default, #faf7f6);
}
.ds-agent-card-category {
  display: inline-block;
  margin: calc(var(--ds-space-control-gap, 0.5rem) / 4) var(--ds-space-panel-inset, 1rem);
  padding: 0 calc(var(--ds-space-control-gap, 0.5rem) / 2);
  border-radius: var(--ds-radius-compact-control, 0.5rem);
  background: var(--ds-neutral-subtle-default, #faf7f6);
  color: var(--ds-category-amber-text-strong, #5e3d00);
}
.ds-agent-card-rules {
  position: absolute;
  left: calc(var(--ds-space-control-gap, 0.5rem) * 1.25);
  right: calc(var(--ds-space-control-gap, 0.5rem) * 1.25);
  bottom: calc(var(--ds-space-control-gap, 0.5rem) * 1.25);
  padding: calc(var(--ds-space-control-gap, 0.5rem) * 1.25);
  background: color-mix(
    in srgb,
    var(--ds-neutral-subtle-default, #faf7f6) 94%,
    var(--ds-category-amber-background-subtle, #fff9f1)
  );
  color: var(--ds-ink-default-default, #1d1d1d);
  border: 1px solid var(--ds-category-amber-border-default, #ffd192);
}
.ds-agent-card-face--silver .ds-agent-card-rules,
.ds-agent-card-face--ink .ds-agent-card-rules {
  background: var(--ds-neutral-subtle-default, #faf7f6);
  color: var(--ds-ink-default-default, #1d1d1d);
  border-color: var(--ds-category-slate-border-default, #ccd1d9);
}
.ds-agent-card-summary {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  min-height: 32px;
  margin-top: calc(var(--ds-space-control-gap, 0.5rem) / 2);
  overflow-wrap: anywhere;
}
.ds-agent-card-stats {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-space-control-gap, 0.5rem);
  margin-top: var(--ds-space-control-gap, 0.5rem);
  padding-top: calc(var(--ds-space-control-gap, 0.5rem) * 0.75);
  border-top: 1px solid var(--ds-hairline-default-default, rgba(29, 29, 29, 0.149));
}
.ds-agent-card-actions {
  display: flex;
  align-items: center;
  gap: calc(var(--ds-space-control-gap, 0.5rem) / 2);
  margin-top: var(--ds-space-control-gap, 0.5rem);
}
.ds-agent-card-face--classic .ds-agent-card-art {
  top: 24%;
  left: var(--ds-space-control-inline, 0.75rem);
  right: var(--ds-space-control-inline, 0.75rem);
  bottom: 34%;
}
.ds-library-choice{display:block;width:256px;max-width:100%;padding:6px;border:0;border-radius:var(--ds-radius-card, 1rem);background:transparent;color:inherit;text-align:left;cursor:pointer;font-family:var(--ds-font-text, Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif);}.ds-library-choice .ds-agent-card-face{display:block;height:auto;}.ds-agent-card-title{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--ds-font-text, Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif);font-size:var(--ds-text-title-size, 1.125rem);line-height:var(--ds-text-title-line, 1.5rem);font-weight:600;}.ds-agent-card-rules{display:block;}.ds-agent-card-category,.ds-agent-card-rules{font-family:var(--ds-font-text, Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif);font-size:var(--ds-text-meta-size, 0.6875rem);line-height:var(--ds-text-meta-line, 1rem);}.ds-agent-card-capability{display:block;font-weight:600;}.ds-library-choice:hover .ds-agent-card-face{transform:translateY(-2px);}.ds-library-choice[aria-pressed="true"]{outline:2px solid var(--ds-ring-focus, rgba(15, 13, 8, 0.620));outline-offset:0;}.ds-library-choice:focus-visible{outline:2px solid var(--ds-ring-focus, rgba(15, 13, 8, 0.620));outline-offset:2px;}.ds-library-choice:disabled{pointer-events:none;}@media(prefers-reduced-motion:reduce){.ds-library-choice:hover .ds-agent-card-face{transform:none;}}@media(forced-colors:active){.ds-agent-card-face,.ds-agent-card-rules{border-color:CanvasText;}}
